struct TestStats {
    uint32_t passed;
    uint32_t failed;
    uint32_t total;
};
static TestStats g_stats = {0, 0, 0};

struct SpacetimeSim {
    float phi[WAVE_GRID_SIZE];
    float phi_prev[WAVE_GRID_SIZE];
    float phi_next[WAVE_GRID_SIZE];
    float g00[WAVE_GRID_SIZE];
    float g11[WAVE_GRID_SIZE];
    float source_amplitude;
    uint32_t step;
};

void init_spacetime_sim(SpacetimeSim *sim) {
    std::memset(sim->phi, 0, sizeof(sim->phi));
    std::memset(sim->phi_prev, 0, sizeof(sim->phi_prev));
    std::memset(sim->phi_next, 0, sizeof(sim->phi_next));
    for (int i = 0; i < WAVE_GRID_SIZE; i++) {
        sim->g00[i] = 1.0f;
        sim->g11[i] = 1.0f;
    }
    sim->source_amplitude = 0.0f;
    sim->step = 0;
}

void modulate_metric(SpacetimeSim *sim, float wave1, float wave2, float wave3, float wave4) {
    float coupling = 0.15f * (wave1 + wave2 + wave3 + wave4);
    for (int i = 0; i < WAVE_GRID_SIZE; i++) {
        float dist_from_center = static_cast<float>(std::abs(i - (WAVE_GRID_SIZE / 2)));
        float spatial_profile = std::exp(-(dist_from_center * dist_from_center) / 50.0f);
        sim->g00[i] = 1.0f + coupling * spatial_profile;
        sim->g11[i] = 1.0f / (1.0f + coupling * spatial_profile);
    }
}

void step_spacetime_sim(SpacetimeSim *sim, float dt) {
    if (dt <= 0.0f) {
        std::cout << "  [WARNING] Telemetry query step bypassed: dt must be positive (Received: " << dt << ")\n";
        return;
    }
    float r2 = WAVE_COURANT * WAVE_COURANT;
    sim->source_amplitude = std::sin(0.2f * sim->step * dt);

    for (int i = 1; i < WAVE_GRID_SIZE - 1; i++) {
        float det_g_prev = sim->g00[i-1] * sim->g11[i-1];
        float det_g_curr = sim->g00[i] * sim->g11[i];
        float det_g_next = sim->g00[i+1] * sim->g11[i+1];
        
        float sqrt_g_prev = std::sqrt(std::abs(det_g_prev));
        float sqrt_g_curr = std::sqrt(std::abs(det_g_curr));
        float sqrt_g_next = std::sqrt(std::abs(det_g_next));

        float term_x_next = sqrt_g_next * sim->g11[i+1] * (sim->phi[i+1] - sim->phi[i]);
        float term_x_prev = sqrt_g_prev * sim->g11[i-1] * (sim->phi[i] - sim->phi[i-1]);
        float spatial_div = term_x_next - term_x_prev;

        float factor = r2 / (sqrt_g_curr * sim->g00[i]);
        sim->phi_next[i] = 2.0f * sim->phi[i] - sim->phi_prev[i] + factor * spatial_div;

        if (sim->phi_next[i] != sim->phi_next[i] || sim->phi_next[i] > 1e9f || sim->phi_next[i] < -1e9f) {
            std::cout << "  [CRITICAL] Numerical singularity detected in spacetime wave. Auto-healing...\n";
            init_spacetime_sim(sim);
            return;
        }
    }
    sim->phi_next[0] = sim->source_amplitude;
    sim->phi_next[WAVE_GRID_SIZE - 1] = 0.0f;
    std::memcpy(sim->phi_prev, sim->phi, sizeof(sim->phi));
    std::memcpy(sim->phi, sim->phi_next, sizeof(sim->phi));
    sim->step++;
}

void print_wave_profile(const SpacetimeSim *sim) {
    const int height = 11;
    const int mid_y = height / 2;
    char display[11][WAVE_GRID_SIZE + 1];
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < WAVE_GRID_SIZE; j++) display[i][j] = (i == mid_y) ? '-' : ' ';
        display[i][WAVE_GRID_SIZE] = '\0';
    }
    for (int i = 0; i < WAVE_GRID_SIZE; i++) {
        float val = sim->phi[i];
        if (val > 1.5f) val = 1.5f;
        if (val < -1.5f) val = -1.5f;
        int y = mid_y - (int)std::round(val * (float)mid_y / 1.5f);
        if (y < 0) y = 0;
        if (y >= height) y = height - 1;
        display[y][i] = (y == mid_y) ? 'o' : '*';
    }
    std::cout << "  [Step " << std::setw(3) << std::setfill('0') << sim->step
              << " | Geodesic Amplitude: " << std::showpos << std::fixed << std::setprecision(4)
              << sim->source_amplitude << "]\n";
    std::cout << "  +----------------------------------------+\n";
    for (int i = 0; i < height; i++) std::cout << "  |" << display[i] << "|\n";
    std::cout << "  +----------------------------------------+\n";
}

int main(int argc, char* argv[]) {
    int sim_steps = 30;
    std::string export_path = "";
    bool silent = false;

    for (int i = 1; i < argc; i++) {
        if ((std::strcmp(argv[i], "--steps") == 0 || std::strcmp(argv[i], "-s") == 0) && i + 1 < argc) {
            sim_steps = std::atoi(argv[++i]);
            if (sim_steps < 1) sim_steps = 1;
            if (sim_steps > 1000000) sim_steps = 1000000;
        } else if ((std::strcmp(argv[i], "--export") == 0 || std::strcmp(argv[i], "-e") == 0) && i + 1 < argc) {
            export_path = argv[++i];
        } else if (std::strcmp(argv[i], "--silent") == 0 || std::strcmp(argv[i], "-q") == 0) {
            silent = true;
        }
    }

    std::cout << "==================================================\n";
    std::cout << "PHASR Satan's Recursion: Curved Spacetime Engine   \n";
    std::cout << "Target Engine: C++ Covariant D'Alembertian Solver \n";
    std::cout << "==================================================\n\n";

    std::cout << "[1/2] Running " << TOTAL_ROUTINES << " Spacetime Audits...\n";
    
    // Evaluate checks using Custom Deterministic Compute Balancer
    SatanStatus ss = { 1, 2, 3, 4, 3, 1, 3, 13 };
    uint32_t passes = 0;
    
    unsigned int num_threads = std::thread::hardware_concurrency();
    if (num_threads < 1) num_threads = 1;
    if (num_threads > NUM_CHUNKS) num_threads = NUM_CHUNKS;

    std::vector<std::thread> workers;
    std::vector<PaddedUInt32> thread_passes(num_threads, PaddedUInt32{0});

    for (unsigned int t = 0; t < num_threads; t++) {
        workers.emplace_back([t, num_threads, &ss, &thread_passes]() {
            // Set Thread Affinity (Core Pinning)
#if 1 // PLATFORM_AGNOSTIC_C_FALLBACK_FORCED
            HANDLE thread = GetCurrentThread();
            DWORD_PTR mask = 1ULL << (t % std::thread::hardware_concurrency());
            SetThreadAffinityMask(thread, mask);
#elif defined(__linux__)
            cpu_set_t cpuset;
            CPU_ZERO(&cpuset);
            CPU_SET(t % std::thread::hardware_concurrency(), &cpuset);
            pthread_setaffinity_np(pthread_self(), sizeof(cpu_set_t), &cpuset);
#endif

            uint32_t local_passes = 0;
            // Static round-robin chunk assignment (Deterministic load balancing)
            for (int chunk = t; chunk < NUM_CHUNKS; chunk += num_threads) {
                for (int r = 0; r < ROUTINES_PER_CHUNK; r++) {
                    int idx = chunk * ROUTINES_PER_CHUNK + r;
                    if (g_satan_checks[idx](&ss)) {
                        local_passes++;
                    }
                }
                // Paced duty cycling (sleep 1ms per chunk to prevent thermal spike)
                std::this_thread::sleep_for(std::chrono::milliseconds(1));
            }
            thread_passes[t].value = local_passes;
        });
    }

    for (unsigned int t = 0; t < num_threads; t++) {
        if (workers[t].joinable()) {
            workers[t].join();
        }
        passes += thread_passes[t].value;
    }
    
    std::cout << "      Assertions Run: " << TOTAL_ROUTINES << "\n";
    std::cout << "      Passed: " << passes << " | Failed: " << (TOTAL_ROUTINES - passes) << "\n";
    
    if (passes == TOTAL_ROUTINES) {
        std::cout << "      SUCCESS: Curved spacetime metrics attestation complete.\n\n";
    } else {
        std::cout << "      WARNING: Singularity metrics deviation detected!\n\n";
    }

    std::cout << "[2/2] Running Geodesic Wave Propagation Simulation...\n";
    std::cout << "      Instances to run: " << sim_steps << "\n";
    std::cout << "      Equation: Box_g (Psi) = 0 (Covariant Spacetime Wave Solver)\n\n";

    SpacetimeSim sim;
    init_spacetime_sim(&sim);

    std::ofstream out_file;
    if (!export_path.empty()) {
        out_file.open(export_path, std::ios::binary);
        if (!out_file) {
            std::cerr << "[ERROR] Failed to open export file: " << export_path << "\n";
            return 1;
        }
        uint32_t grid_size = WAVE_GRID_SIZE;
        uint32_t total_steps = sim_steps;
        out_file.write(reinterpret_cast<const char*>(&grid_size), sizeof(grid_size));
        out_file.write(reinterpret_cast<const char*>(&total_steps), sizeof(total_steps));
    }

    modulate_metric(&sim, 0.9f, 0.85f, 0.95f, 0.92f);

    float dt = 0.1f;
    for (int step = 0; step < sim_steps; step++) {
        step_spacetime_sim(&sim, dt);
        if (out_file.is_open()) {
            out_file.write(reinterpret_cast<const char*>(sim.phi), sizeof(sim.phi));
        }
        if (!silent && sim_steps <= 100) {
            if (step % 3 == 0) {
                print_wave_profile(&sim);
                std::cout << "\n";
            }
        }
    }

    if (out_file.is_open()) {
        out_file.close();
        std::cout << "      SUCCESS: Exported " << sim_steps << " steps of spacetime grid simulation to " << export_path << "\n";
    }

    std::cout << "Spacetime simulation telemetry sequence complete.\n";
    std::cout << "==================================================\n";
    return (passes == TOTAL_ROUTINES) ? 0 : 1;
}
